def compute(vars):
    value_2018 = vars["v1"]
    value_2019 = vars["v2"]
    higher_year = 2019 if value_2019 > value_2018 else 2018 if value_2018 > value_2019 else None

    return {
        "value": higher_year,
        "trace": {
            "value_2018": value_2018,
            "value_2019": value_2019,
            "higher_year": higher_year,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
